# Generated by test-lab — blind adversarial evaluation
"""Verifier regression tests for /ask argue."""

from ask.argue import verify_argue_result


def _citation(source_id: str = "QUESTION") -> dict[str, str]:
    return {
        "source_id": source_id,
        "source_kind": "question",
        "quote_or_summary": "The release config contract says missing config returns needs_attention.",
        "supports": "verdict",
    }


def _advocate(side: str) -> dict:
    return {
        "side": side,
        "position": f"{side} position",
        "strongest_argument": "The release config contract says missing config returns needs_attention.",
        "evidence": ["The release config contract says missing config returns needs_attention."],
        "evidence_citations": [_citation()],
        "assumptions": ["The question contract is authoritative."],
        "weaknesses": ["No implementation evidence is supplied."],
        "missing_evidence": ["Implementation test output."],
        "response_to_opposition": "The opposition does not overturn the stated contract.",
        "what_would_change_my_mind": ["Contrary contract text."],
        "confidence": "medium",
        "scillm": {"source_grounding_status": "retry_without_source_after_error"},
    }


def _judge(verdict: str = "FOR") -> dict:
    return {
        "verdict": verdict,
        "confidence": "medium",
        "decision_required": False,
        "tie_breaker": "",
        "decision_criterion": "Use the explicit release config contract.",
        "winning_side": verdict if verdict in {"FOR", "AGAINST"} else "none",
        "deciding_factors": ["The release config contract directly supports the verdict."],
        "strongest_for_argument": "The contract requires needs_attention.",
        "strongest_against_argument": "Implementation evidence is absent.",
        "strongest_counterargument": "Implementation evidence is absent.",
        "why_counterargument_does_or_does_not_win": "The verdict is limited to the stated contract.",
        "evidence_used": ["The release config contract says missing config returns needs_attention."],
        "evidence_citations": [_citation()],
        "assumptions": ["The contract text in the question is authoritative."],
        "missing_evidence": ["Implementation test output."],
        "what_would_change_the_verdict": ["Contrary contract text."],
        "recommended_next_action": "Add an implementation test.",
        "uncertainty_disclosure": "Implementation behavior still needs a test.",
        "scillm": {"source_grounding_status": "retry_without_source_after_error"},
    }


def _result(judge: dict) -> dict:
    return {
        "source_bundle": {
            "sources": [
                {
                    "source_id": "QUESTION",
                    "kind": "question",
                    "content": "The release config contract says missing config returns needs_attention.",
                }
            ]
        },
        "for_case": _advocate("FOR"),
        "against_case": _advocate("AGAINST"),
        "judge": judge,
    }


def test_for_verdict_passes_with_schema_and_citations_when_proxy_grounding_degraded():
    verifier = verify_argue_result(_result(_judge("FOR")))

    assert verifier["status"] == "PASS"
    assert verifier["grounding_degraded"] is True


def test_for_verdict_fails_without_admissible_citation():
    judge = _judge("FOR")
    judge["evidence_citations"] = [_citation("MEMORY.404")]

    verifier = verify_argue_result(_result(judge))

    assert verifier["status"] == "FAIL"
    assert any("admissible source-bundle citation" in failure for failure in verifier["failures"])


def test_insufficient_evidence_is_successful_safe_verdict_with_missing_evidence():
    judge = _judge("INSUFFICIENT_EVIDENCE")

    verifier = verify_argue_result(_result(judge))

    assert verifier["status"] == "PASS"
